package com.example; import net.fabricmc.api.ClientModInitializer; import net.fabricmc.fabric.api.event.player.UseBlockCallback; import net.minecraft.block.BlockState; import net.minecraft.block.Blocks; import net.minecraft.block.RespawnAnchorBlock; import net.minecraft.entity.player.PlayerInventory; import net.minecraft.item.ItemStack; import net.minecraft.item.Items; import net.minecraft.text.Text; import net.minecraft.util.ActionResult; import net.minecraft.util.Hand; public class SafeAnchorMod implements ClientModInitializer { @Override public void onInitializeClient() { UseBlockCallback.EVENT.register((player, world, hand, hitResult) -> { if (!world.isClient() || hand != Hand.MAIN_HAND) return ActionResult.PASS; BlockState state = world.getBlockState(hitResult.getBlockPos()); if (state.isOf(Blocks.RESPAWN_ANCHOR)) { int charges = state.get(RespawnAnchorBlock.CHARGES); ItemStack held = player.getStackInHand(hand); if (charges < 4 && !held.isOf(Items.GLOWSTONE)) { int slot = findGlowstone(player.getInventory()); if (slot != -1) { player.getInventory().selectedSlot = slot; player.sendMessage(Text.literal("§a[SafeAnchor] Auto-swapped to Glowstone!"), true); return ActionResult.PASS; } } if (charges > 0 && !held.isOf(Items.GLOWSTONE) && !world.getDimension().respawnAnchorWorks()) { if (!player.isSneaking()) { player.sendMessage(Text.literal("§c[SafeAnchor] Blocked! Sneak to pop."), true); return ActionResult.FAIL; } } } return ActionResult.PASS; }); } private int findGlowstone(PlayerInventory inv) { for (int i = 0; i < 9; i++) { if (inv.getStack(i).isOf(Items.GLOWSTONE)) return i; } return -1; } }
